INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41811, 'Ezekiel 13:9', 'Ezekiel', 13, 9, 'زه به خپل لاس د هغو ټولو پیغمبرانو په خلاف پورته کړم چې بې‌ارزښته رویاګانې ویني او دروغجنې پېشګویانې کوي. هغوی به زما د قوم د ټولنې څخه وشړل شي. زه به د هغوی نومونه د اسرایيلو د لست نه لېرې کړم او هغوی به بيا هيڅکله په خپل وطن کې پښې کښېنږدي. نو بیا به په دې پوه شئ چې زه څښتن تعالی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_9.mp3', '', 1761754199, 1761754199),
(41812, 'Ezekiel 13:10', 'Ezekiel', 13, 10, 'پیغمبران زما قوم بې‌لارې کوي او وایي چې خیر خیریت دی. خو په رښتیا سره خیریت نه دی! زما قوم یو کمزوری دېوال جوړ کړی دی او پیغمبران راغلي دي او هغه یې په چونه او ګچو باندې سپین کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_10.mp3', '', 1761754199, 1761754199),
(41813, 'Ezekiel 13:11', 'Ezekiel', 13, 11, 'دې پیغمبرانو ته ووایه چې دېوال به راوغورځیږي. سخت باران به ووریږي، ږلۍ به ووریږي او یو توفان به ورباندې راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_11.mp3', '', 1761754199, 1761754199),
(41814, 'Ezekiel 13:12', 'Ezekiel', 13, 12, 'کله چې دېوال راوغورځیږي، نو هرڅوک به ستاسو نه پوښتنه کوي چې د دېوال د سپینولو څه ګټه وه؟›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_12.mp3', '', 1761754199, 1761754199),
(41815, 'Ezekiel 13:13', 'Ezekiel', 13, 13, 'په دې خاطر څښتن تعالی داسې وایي: ‹زه به په خپل قهر سره یو توفان، سخت باران او ږلۍ نازل کړم چې هغه دېوال وران کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_13.mp3', '', 1761754199, 1761754199),
(41816, 'Ezekiel 13:14', 'Ezekiel', 13, 14, 'زه غواړم چې هغه چونه شوی دېوال راوغورځوم او هغه به د ځمکې سره هوار کړم او د بنیاد تیږې به یې راښکاره شي. هغه به راولویږي او تاسو ټول به مړه کړي. بیا به ټول په دې پوه شي چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_14.mp3', '', 1761754199, 1761754199),
(41817, 'Ezekiel 13:15', 'Ezekiel', 13, 15, 'نو زما قهر به په دېوال او په هغه چا چې هغه یې رنګ کړی دی، سوړ شي. بیا به تاسو ته ووایم چې هغه دېوال او د هغه رنګ کوونکي نور نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_15.mp3', '', 1761754199, 1761754199),
(41818, 'Ezekiel 13:16', 'Ezekiel', 13, 16, 'دا هغه پیغمبران وو چې په ډاډه زړه سره به یې ویل چې په اورشلیم کې خیر خیریت دی، خو حال دا چې هلته خیریت نه ؤ.› څښتن تعالی داسې ویلي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_16.mp3', '', 1761754199, 1761754199),
(41819, 'Ezekiel 13:17', 'Ezekiel', 13, 17, 'څښتن وویل: «ای فاني انسانه، د اسراییلو هغه ښځې محکومې کړه چې له خپله ځانه پېشګویي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_17.mp3', '', 1761754199, 1761754199),
(41820, 'Ezekiel 13:18', 'Ezekiel', 13, 18, 'هغوی ته ووایه چې څښتن تعالی ورته داسې وایي: ‹افسوس ستاسو په حال! تاسو هرچا ته د کوډو تعویذونه جوړوئ چې په خپلو مړوندونو باندې یې وتړي او هرچا ته د هغه د قد په اندازه د کوډو دستمالونه جوړوئ چې خپل سرونه ورباندې وتړي، ترڅو وکولای شئ د نورو خلکو د ژوند واک ولرئ. ایا تاسو غواړئ چې زما د خلکو د ژوند او مرګ اختیار تر‌لاسه کړئ او د هغه څخه د خپل ځان په ګټه کار واخلئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_18.mp3', '', 1761754199, 1761754199),
(41821, 'Ezekiel 13:19', 'Ezekiel', 13, 19, 'تاسو د څو موټو اوربشو او د څو ټوټو ډوډیو په خاطر زما د قوم په مخکې زما سپکاوی وکړ. تاسو هغه خلک وژنئ کوم چې د مرګ لایق نه دي او هغه خلک ژوندي پرېږدئ کوم چې د ژوندي پرېښودلو لایق نه دي. تاسو زما خلکو ته دروغ وایئ او هغوی په تاسو باندې یقین کوي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_19.mp3', '', 1761754199, 1761754199),
(41822, 'Ezekiel 13:20', 'Ezekiel', 13, 20, 'نو څښتن تعالی داسې وایي: ‹ګورئ، زه د کوډو د تعویذونو په ضد یم چې تاسو یې په مرګ او ژوند باندې د قدرت ترلاسه کولو په خاطر د خلکو په مټو باندې تړئ. زه به هغه ستاسو د مټو څخه وشکوم او هغه خلک به خلاص کړم چې تاسو د مرغیو په شان په دام کې راګېر کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_20.mp3', '', 1761754199, 1761754199),
(41823, 'Ezekiel 13:21', 'Ezekiel', 13, 21, 'زه به ستاسو د سرونو دستمالونه وشکوم او خپل قوم به خلاص کړم او نور به ونه شئ کولائ په خپل دام کې هغوی راګېر کړئ. نو بیا به تاسو پوه شئ چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_21.mp3', '', 1761754199, 1761754199),
(41824, 'Ezekiel 13:22', 'Ezekiel', 13, 22, 'دا ځکه چې تاسو په خپلو دروغو باندې د هغو نېکو خلکو زړونه تور کړي دي چې زه نه غواړم هغوی خفه کړم. تاسو بدعمله خلک دې ته هڅولي دي چې د خپلو بدو کارونو نه لاس وانخلي او خپل ژوند وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_22.mp3', '', 1761754199, 1761754199),
(41825, 'Ezekiel 13:23', 'Ezekiel', 13, 23, 'نو اوس به تاسو بې‌ارزښته رویاګانې ونه وینئ او بې‌لارې کوونکې پېشګویانې به نه کوئ. زه به خپل قوم ستاسو د منګولو نه خلاص کړم، نو هغه وخت به په دې پوه شئ چې زه څښتن یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_23.mp3', '', 1761754199, 1761754199),
(41826, 'Zechariah 13:1', 'Zechariah', 13, 1, '”په هغه ورځ به چينه د داؤد د خاندان او د يروشلم اوسېدونکو دپاره کولاو شى چې دوئ د ګناه او ناپاکۍ نه پاک کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah13_verse_1.mp3', '', 1761754199, 1761754199),
(41827, 'Zechariah 13:2', 'Zechariah', 13, 2, 'په هغه ورځ به زۀ د بُتانو نومونه د مُلک نه ختم کړم، هغوئ به نور نۀ ياديږى،“ مالِک خُدائ ربُ الافواج فرمائى. ”زۀ به دروغژن پېغمبران او ناپاکه روحونه دواړه د مُلک نه ختم کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah13_verse_2.mp3', '', 1761754199, 1761754199),
(41828, 'Zechariah 13:3', 'Zechariah', 13, 3, 'او کۀ اوس هم څوک پېشګوئې کوى، د هغۀ پلار او مور، چا نه چې هغه پېدا دے، به هغۀ ته وائى، تۀ به ضرور مړ شې، ځکه چې تا د مالِک خُدائ په نوم دروغ ووئيل. کله چې هغه پېشګوئې کوى د هغۀ خپل پلار مور به يې وڅيرى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah13_verse_3.mp3', '', 1761754199, 1761754199),
(41829, 'Zechariah 13:4', 'Zechariah', 13, 4, 'په هغه ورځ به پېغمبران په پېشګوئې کولو او په رويا بيانولو شرميږى. د پېغمبرانو په ببره چُوغه اچولو به څوک هم نۀ دوکه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah13_verse_4.mp3', '', 1761754199, 1761754199),
(41830, 'Zechariah 13:5', 'Zechariah', 13, 5, 'هغه به وائى، زۀ پېغمبر نۀ يم. زۀ زميندار يم، زمکه د ځوانۍ نه زما روزګار دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah13_verse_5.mp3', '', 1761754199, 1761754199),
(41831, 'Zechariah 13:6', 'Zechariah', 13, 6, 'کۀ څوک ترې نه تپوس وکړى، دا زخمونه ستا په بدن باندې د څۀ دى؟ هغه به جواب ورکړى، دا زخمونه په ما باندې زما د ملګرى کور کښې لګېدلى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah13_verse_6.mp3', '', 1761754199, 1761754199),
(41832, 'Zechariah 13:7', 'Zechariah', 13, 7, 'اے تُورې، زما د شپونکى خلاف راپاڅه، د هغه سړى خلاف چې زما ملګرے دے.“ مالِک خُدائ ربُ الافواج فرمائى. ”زۀ به شپون ووهم، او ګډې به يې خورې ورې شى، او زۀ به خپل لاس د هغوئ خلاف اوږد کړم چې واړۀ دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah13_verse_7.mp3', '', 1761754199, 1761754199),
(41833, 'Zechariah 13:8', 'Zechariah', 13, 8, 'په ټول مُلک کښې،“ مالِک خُدائ فرمائى، ”په درېو کښې به دوه مړۀ او تباه شى، درېو کښې به يو پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah13_verse_8.mp3', '', 1761754199, 1761754199),
(41834, 'Zechariah 13:9', 'Zechariah', 13, 9, 'دا درېمه برخه به زۀ اور کښې واچوم، زۀ به دوئ لکه د سپينو زرو په شان صفا کړم او لکه د سرو زرو به يې وآزمائيم. هغوئ به زما په نوم آواز وکړى او زۀ به هغوئ له جواب ورکړم، او زۀ به ووايم چې، دوئ زما خلق دى، او هغوئ به وائى، مالِک خُدائ زمونږ خُدائ پاک دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah13_verse_9.mp3', '', 1761754199, 1761754199),
(41835, 'Genesis 48:1', 'Genesis', 48, 1, 'څه موده وروسته یوسف ته خبر ورسېده چې پلار یې ناروغ دی. نو هغه خپل دواړه زامن منسي او افرایم د ځان سره واخیستل او د خپل پلار لیدلو ته ورغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_1.mp3', '', 1761754199, 1761754199),
(41836, 'Genesis 48:2', 'Genesis', 48, 2, 'کله چې یعقوب خبر شو چې د هغه زوی یوسف د هغه د لیدلو دپاره راغلی دی، نو هغه د خپل ټول قوت څخه کار واخیست، ترڅو په خپل کټ باندې کښېناست.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_2.mp3', '', 1761754199, 1761754199),
(41837, 'Genesis 48:3', 'Genesis', 48, 3, 'یعقوب یوسف ته وویل: «مطلق قادر خدای ماته د کنعان په وطن کې په لوز کې راښکاره شو او برکت یې راته راکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_3.mp3', '', 1761754199, 1761754199),
(41838, 'Genesis 48:4', 'Genesis', 48, 4, 'ماته یې وویل: ‹تاته به زیات اولادونه درکړم. ستا د نسل څخه به زیات قومونه جوړ کړم او دغه ځمکه به ستا څخه وروسته ستا اولادې ته د هغوی د تلپاتې ملکیت په توګه ورکړم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_4.mp3', '', 1761754199, 1761754199),
(41839, 'Genesis 48:5', 'Genesis', 48, 5, 'نو اوس ستا دوه زامن چې زما د راتللو څخه مخکې په مصر کې زېږېدلي وو، هغوی زما دي. افرایم او منسي د روبین او شمعون په شان زما زامن دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_5.mp3', '', 1761754199, 1761754199),
(41840, 'Genesis 48:6', 'Genesis', 48, 6, 'له دوی څخه وروسته چې ستا کوم اولادونه پیدا کیږي هغه به ستا وي او د هغوی میراث به د افرایم او منسي څخه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_6.mp3', '', 1761754199, 1761754199),
(41841, 'Genesis 48:7', 'Genesis', 48, 7, 'کله چې زه د بین‌النهرین څخه راتللم، نو په خواشینۍ سره راحیل د کنعان په خاوره کې افراتې ته نژدې په لاره کې مړه شوه. نو هغه مې د افراتې د لارې تر‌څنګه ښخه کړه.» (هغه ځای اوس د بیت‌لحم په نوم یادیږي.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_7.mp3', '', 1761754199, 1761754199),
(41842, 'Genesis 48:8', 'Genesis', 48, 8, 'کله چې یعقوب د یوسف زامن ولیدل، هغه پوښتنه وکړه: «دا څوک دي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_8.mp3', '', 1761754199, 1761754199),
(41843, 'Genesis 48:9', 'Genesis', 48, 9, 'یوسف خپل پلار ته وویل: «دا زما زامن دي چې خدای ماته دلته په مصر کې راکړي دي.» بیا یعقوب وویل: «هغوی ماته راوله چې زه ورته برکت ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_9.mp3', '', 1761754199, 1761754199),
(41844, 'Genesis 48:10', 'Genesis', 48, 10, 'د یعقوب سترګې د زوړوالي له امله دومره کمزورې شوې وې چې څه شی ورته سم نه ښکاره کېده. نو یوسف خپل زامن هغه ته ورنژدې کړل او د هغه پلار هغوی ښکل کړل او په خپل غېږ کې یې ونیول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_10.mp3', '', 1761754199, 1761754199),
(41845, 'Genesis 48:11', 'Genesis', 48, 11, 'یعقوب یوسف ته وویل: «ما هېڅکله دا هیله نه درلودله چې ستا مخ به بیا ووینم او اوس خدای زه دې ته پرېښودم چې ستا اولادونه هم ووینم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_11.mp3', '', 1761754199, 1761754199),
(41846, 'Genesis 48:12', 'Genesis', 48, 12, 'بیا یوسف هغوی د خپل پلار د زنګنونو څخه لېرې کړل او د درناوي په خاطر یې هغه ته خپل سر ټیټ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_12.mp3', '', 1761754199, 1761754199),
(41847, 'Genesis 48:13', 'Genesis', 48, 13, 'یوسف افرایم د یعقوب چپ لاس ته او منسي یې د هغه ښي لاس ته نژدې راوستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_13.mp3', '', 1761754199, 1761754199),
(41848, 'Genesis 48:14', 'Genesis', 48, 14, 'خو یعقوب خپل ښي لاس اوږد کړ او هغه یې د افرایم په سر باندې کېښود، که څه هم هغه کشر ؤ او خپل چپ لاس یې د منسي په سر باندې چې مشر ؤ، کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_14.mp3', '', 1761754199, 1761754199),
(41849, 'Genesis 48:15', 'Genesis', 48, 15, 'بیا هغه یوسف ته برکت ورکړ او ویې ویل: «هغه خدای چې زما پلرونو ابراهیم او اسحاق یې خدمت کړی دی، هغه دې دغو هلکانو ته برکت ورکړي! هغه خدای چې تر دې ورځې پورې یې زما لارښوونه کړې، هغوی ته دې برکت ورکړي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_15.mp3', '', 1761754199, 1761754199),
(41850, 'Genesis 48:16', 'Genesis', 48, 16, 'هغه فرښته دې هغوی ته برکت ورکړي چې زه یې د ټولو بدیو څخه ژغورلی یم! زما او زما د نیکونو ابراهیم او اسحاق نومونه دې د دوی په وسیله ژوندي وساتل شي او هغوی دې ډېره اولاده ولري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_16.mp3', '', 1761754199, 1761754199),
(41851, 'Genesis 48:17', 'Genesis', 48, 17, 'کله چې یوسف ولیدل چې پلار یې خپل ښي لاس د افرایم په سر باندې کېښود هغه خفه شو. نو د خپل پلار لاس یې ونیوه چې د افرایم له سر څخه یې د منسي سرته راواړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_17.mp3', '', 1761754199, 1761754199),
(41852, 'Genesis 48:18', 'Genesis', 48, 18, 'یوسف هغه ته وویل: «نه پلاره، دغه مشر دی. خپل ښي لاس دې د هغه په سر باندې کېږده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_18.mp3', '', 1761754199, 1761754199),
(41853, 'Genesis 48:19', 'Genesis', 48, 19, 'د هغه پلار انکار وکړ او ویې ویل: «ای زویه، زه پوهېږم! زه پوهېږم چې د منسي څخه به هم یو لوی قوم جوړ شي. خو د هغه کشر ورور به د هغه څخه لوی سړی شي، ځکه چې د هغه د اولادې څخه به لوی قومونه پیدا شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_19.mp3', '', 1761754199, 1761754199),
(41854, 'Genesis 48:20', 'Genesis', 48, 20, 'په هغه ورځ یعقوب هغوی ته برکت ورکړ او ویې ویل: «د اسراییلو قوم به یو بل ته ستاسو په نوم برکت غواړي او داسې به وایي چې خدای دې تا د افرایم او منسي په شان کړي.» په دې ډول یعقوب افرایم ته په منسي باندې د لومړي‌توب حق ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_20.mp3', '', 1761754199, 1761754199),
(41855, 'Genesis 48:21', 'Genesis', 48, 21, 'بیا یعقوب یوسف ته وویل: «ګوره، زه مرګ ته نژدې یم، خو خدای به تاسو سره مل وي او تاسو به بېرته د خپلو نیکونو وطن ته بوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_21.mp3', '', 1761754199, 1761754199),
(41856, 'Genesis 48:22', 'Genesis', 48, 22, 'د شکیم هغه حاصلخېزه سیمه چې ما د اموریانو څخه د خپلې تورې او لیندې په زور نیولې ده، ستا ورونو ته نه، بلکې تاته درکوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis48_verse_22.mp3', '', 1761754199, 1761754199),
(41857, 'Psalms 36:1', 'Psalms', 36, 1, 'د زړه په تل کې د بدکاره خلکو کوي ګناه خبرې هغوی هېڅ وېریږي نه له خدایه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms36_verse_1.mp3', '', 1761754199, 1761754199),
(41858, 'Psalms 36:2', 'Psalms', 36, 2, 'دا چې دوی ځان ته ډېر اوچت فکر کړي فکر کوي چې خدای به نه کړي پیدا د دوی ګناه او نه به یې وغندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms36_verse_2.mp3', '', 1761754199, 1761754199),
(41859, 'Psalms 36:3', 'Psalms', 36, 3, 'د دوی د خولې خبرې بدې، له دروغو ډکې دوی نور نه کړي عقلمن کار او نېکي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms36_verse_3.mp3', '', 1761754199, 1761754199),
(41860, 'Psalms 36:4', 'Psalms', 36, 4, 'کله چې پروت وي بستره کې پلانونه د بدۍ جوړوي هغه خپل ځان په بده لار بوځي نه اخلي لاس له بده کاره ځینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms36_verse_4.mp3', '', 1761754199, 1761754199),
(41861, 'Psalms 36:5', 'Psalms', 36, 5, 'تلپاتې مینه دې رسیږي اسمانونو پورې ای څښتنه وفاداري دې تر فلکه رسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms36_verse_5.mp3', '', 1761754199, 1761754199),
(41862, 'Psalms 36:6', 'Psalms', 36, 6, 'ستا عدالت داسې قایم دی د لوړو غرونو په شان د ستا انصاف لکه ژور دریاب دی ته پام کوې په انسانانو او حیواناتو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms36_verse_6.mp3', '', 1761754199, 1761754199),
(41863, 'Psalms 36:7', 'Psalms', 36, 7, 'دا ستا تلپاتې مینه څومره قیمتي ده خدایه! ستا د وزرو لاندې پناه اخلي ټول خلک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms36_verse_7.mp3', '', 1761754199, 1761754199),
(41864, 'Psalms 36:8', 'Psalms', 36, 8, 'کړي د پرېمانه خوړو ستا نه خوراکونه هغوی خپل د خوښۍ د سیند نه دوی ته، ته اوبه ورکوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms36_verse_8.mp3', '', 1761754199, 1761754199),
(41865, 'Psalms 36:9', 'Psalms', 36, 9, 'یې د ژوندون سرچینه ستا د نور په سبب وینو مونږ رڼا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms36_verse_9.mp3', '', 1761754199, 1761754199),
(41866, 'Psalms 36:10', 'Psalms', 36, 10, 'څوک چې تا پېژني هغو سره کوه مینه تلپاتې مینه څوک چې نېکان دي د هغوی سره نېکي کوه ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms36_verse_10.mp3', '', 1761754199, 1761754199),
