(41871, 'Psalms 149:3', 'Psalms', 149, 3, 'د هغه د نوم ثنا او صفت وکړئ په اتڼونو باندې د چمبو او چنګونو په وهلو یې ثنا ووایئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms149_verse_3.mp3', '', 1761754199, 1761754199),
(41872, 'Psalms 149:4', 'Psalms', 149, 4, 'ځکه خوشحاله دی څښتن د خپلو خلکو څخه عاجزانو ته په سر ږدي د بري تاج', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms149_verse_4.mp3', '', 1761754199, 1761754199),
(41873, 'Psalms 149:5', 'Psalms', 149, 5, 'خوشحالي دې وکړي خدای ته وفادار خلک خپلې کامیابۍ باندې او په خپلو بسترو کې دې د خوښۍ سندرې ووایي دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms149_verse_5.mp3', '', 1761754199, 1761754199),
