(41875, 'Psalms 149:7', 'Psalms', 149, 7, 'چې د قومونو نه بدل واخلي او سزا ورکړي هغو خلکو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms149_verse_7.mp3', '', 1761754199, 1761754199),
(41876, 'Psalms 149:8', 'Psalms', 149, 8, 'او زولانه کړي د هغوی پاچاهان او په زنځیرونو یې مشران وتړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms149_verse_8.mp3', '', 1761754199, 1761754199),
(41877, 'Psalms 149:9', 'Psalms', 149, 9, 'او لکه څنګه چې خدای حکم کړی چې نورو قومونو ته سزا ورکړي دا کامیابي به وي د خدای د وفادارو خلکو د څښتن ثنا او صفت وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms149_verse_9.mp3', '', 1761754199, 1761754199),
(41878, 'Psalms 54:1', 'Psalms', 54, 1, 'ته په خپل واک باندې ما خلاص کړه خدایه وکړه قضاوت د عدالت په خپل قوت زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms54_verse_1.mp3', '', 1761754199, 1761754199),
(41879, 'Psalms 54:2', 'Psalms', 54, 2, 'خدایه زما دعا قبوله کړه ته زما خبرو ته ته غوږ ونیسه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms54_verse_2.mp3', '', 1761754199, 1761754199),
(41880, 'Psalms 54:3', 'Psalms', 54, 3, 'پردي خلک کړي په ما باندې حمله ظالمان کوي کوښښ چې ومې وژني هغه دي چې نه لري پروا د خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms54_verse_3.mp3', '', 1761754199, 1761754199),
(41881, 'Psalms 54:4', 'Psalms', 54, 4, 'خو خدای زما دی مددګار څښتن ساتونکی دی زما د ژوند', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms54_verse_4.mp3', '', 1761754199, 1761754199),
(41882, 'Psalms 54:5', 'Psalms', 54, 5, 'خدای دې راوګرځوي خپل بد عملونه په دښمن زما ای خدایه زما د حفاظت وعده په ځای کړه او ته ختم یې کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms54_verse_5.mp3', '', 1761754199, 1761754199),
(41883, 'Psalms 54:6', 'Psalms', 54, 6, 'د رضاکاره نذرانې سره به تاته قرباني کومه ای څښتنه زه به شکر ستا کومه ځکه ته یې مهربانه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms54_verse_6.mp3', '', 1761754199, 1761754199),
(41884, 'Psalms 54:7', 'Psalms', 54, 7, 'زه دې د ټولو تکلیفونو نه خلاص کړی یمه په خپلو سترګو د دښمن ماتې لیدلې ده ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms54_verse_7.mp3', '', 1761754199, 1761754199),
(41885, 'Proverbs 9:1', 'Proverbs', 9, 1, 'حکمت د یوې ښځې په څېر خپل کور ودان کړی دی او اووه ستنې یې توږلې او بیا یې ودرولې دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_1.mp3', '', 1761754199, 1761754199),
(41886, 'Proverbs 9:2', 'Proverbs', 9, 2, 'هغې د مېلمستیا دپاره غوښه تیاره کړې او د انګورو شیره یې جوړه کړې ده او دسترخوان یې هوار کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_2.mp3', '', 1761754199, 1761754199),
(41887, 'Proverbs 9:3', 'Proverbs', 9, 3, 'هغې خپلې وینځې ورولېږلې چې د ښار له لوړو ځایونو نه خپل غږ پورته کړي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_3.mp3', '', 1761754199, 1761754199),
(41888, 'Proverbs 9:4', 'Proverbs', 9, 4, '«هرڅوک چې ساده وي، دلته دې راشي!» او بیا ناپوهه خلکو ته وایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_4.mp3', '', 1761754199, 1761754199),
(41889, 'Proverbs 9:5', 'Proverbs', 9, 5, '«راشئ! زما ډوډۍ وخورئ او لږه د انګورو شیره وڅښئ کوم چې ما جوړه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_5.mp3', '', 1761754199, 1761754199),
(41890, 'Proverbs 9:6', 'Proverbs', 9, 6, 'خپله د ناپوهۍ لار پرېږدئ نو تاسو به نېکمرغه ژوند ولرئ او د عقل په لاره به روان شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_6.mp3', '', 1761754199, 1761754199),
(41891, 'Proverbs 9:7', 'Proverbs', 9, 7, 'څوک چې ملنډې وهونکی اصلاح کوي نو ځان شرموي او څوک چې بدکار رټي نو ځان ته زیان رسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_7.mp3', '', 1761754199, 1761754199),
(41892, 'Proverbs 9:8', 'Proverbs', 9, 8, 'د ملنډې وهونکی رټنه مه کوه هسې نه چې ستا نه کرکه وکړي د حکمت د خاوند رټنه کوه نو ستا سره به مینه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_8.mp3', '', 1761754199, 1761754199),
(41893, 'Proverbs 9:9', 'Proverbs', 9, 9, 'د حکمت خاوند ته لارښوونه وکړه نو نور به هم خپل حکمت ډېر کړي نېک سړي ته تعلیم ورکړه چې خپله پوهه نوره هم زیاته کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_9.mp3', '', 1761754199, 1761754199),
(41894, 'Proverbs 9:10', 'Proverbs', 9, 10, 'له څښتن څخه وېره د حکمت شروع ده او عقل د سپېڅلي ذات د پېژندلو علم دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_10.mp3', '', 1761754199, 1761754199),
(41895, 'Proverbs 9:11', 'Proverbs', 9, 11, 'ځکه زما په مرسته به ستا د ژوند ورځې ډېرې شي او ستا د عمر کلونه به نور هم زیات شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_11.mp3', '', 1761754199, 1761754199),
(41896, 'Proverbs 9:12', 'Proverbs', 9, 12, 'که د حکمت خاوند یې نو دا به دې په ګټه وي او که ته ملنډې وهونکی یې نو یوازې زیان به زغمې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_12.mp3', '', 1761754199, 1761754199),
(41897, 'Proverbs 9:13', 'Proverbs', 9, 13, 'کم‌عقلتوب د یوې بې‌حیا ښځې په څېر دی چې ډېره ساده او په هېڅ نه پوهیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_13.mp3', '', 1761754199, 1761754199),
(41898, 'Proverbs 9:14', 'Proverbs', 9, 14, 'هغه د خپل کور د دروازې تر‌څنګ ناسته ده او بیا د ښار په لوړو ځایونو کې په تخت کښېني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_14.mp3', '', 1761754199, 1761754199),
(41899, 'Proverbs 9:15', 'Proverbs', 9, 15, 'څوک چې په خپله لار سم ځي نو هغوی ته نارې وهي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_15.mp3', '', 1761754199, 1761754199),
(41900, 'Proverbs 9:16', 'Proverbs', 9, 16, '«هرڅوک چې ساده وي، دلته دې راشي!» او بیا ناپوهه انسان ته وایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_16.mp3', '', 1761754199, 1761754199),
(41901, 'Proverbs 9:17', 'Proverbs', 9, 17, '«د غلا اوبه خوږې وي او په پټه تر‌لاسه شوې ډوډۍ خوندوره وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_17.mp3', '', 1761754199, 1761754199),
(41902, 'Proverbs 9:18', 'Proverbs', 9, 18, 'هغوی نه پوهیږي چې د هغې په کور کې ټول وژل شوي دي او مېلمانه یې د قبر په ژوره کنده کې پراته دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs9_verse_18.mp3', '', 1761754199, 1761754199),
(41903, 'Zechariah 6:1', 'Zechariah', 6, 1, 'ما بيا بره وکتل، او هلته زما په وړاندې څلور جنګى ګاډۍ د پيتلو د دوو غرونو د مينځ نه راروانې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_1.mp3', '', 1761754199, 1761754199),
(41904, 'Zechariah 6:2', 'Zechariah', 6, 2, 'وړومبۍ ګاډۍ کښې سرۀ آسونه، دوېمه کښې تور آسونه وُو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_2.mp3', '', 1761754199, 1761754199),
(41905, 'Zechariah 6:3', 'Zechariah', 6, 3, 'درېمه کښې سپين آسونه او څلورمه کښې برَګ آسونه وُو، ټول ډېر مضبوط وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_3.mp3', '', 1761754199, 1761754199),
(41906, 'Zechariah 6:4', 'Zechariah', 6, 4, 'ما د هغه فرښتې نه تپوس وکړو چا چې ما سره خبرې کولې، ”دا څۀ دى زما مالِکه؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_4.mp3', '', 1761754199, 1761754199),
(41907, 'Zechariah 6:5', 'Zechariah', 6, 5, 'فرښتې راله جواب راکړو، ”دا د آسمان څلور روحونه دى، دا د ټولې دُنيا د مالِک خُدائ د حضور نه بهر راوتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_5.mp3', '', 1761754199, 1761754199),
(41908, 'Zechariah 6:6', 'Zechariah', 6, 6, 'هغه ګاډۍ چې تور آسونه يې دى د شمال مُلک طرف ته، د سپينو آسونو والا د مغرب طرف ته، او د برَګو آسونو والا د جنوب طرف ته روانه ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_6.mp3', '', 1761754199, 1761754199),
(41909, 'Zechariah 6:7', 'Zechariah', 6, 7, 'کله چې هغه طاقتور آسونه بهر ووتل، نو هغوئ د دُنيا د ګشت لګولو دپاره بې‌صبره وُو. او هغې وفرمائيل، ”لاړ شئ او په دُنيا کښې ګشت ولګوئ.“ نو هغوئ د دُنيا د ګشت لګولو دپاره لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_7.mp3', '', 1761754199, 1761754199),
(41910, 'Zechariah 6:8', 'Zechariah', 6, 8, 'بيا هغې ما ته آواز وکړو چې، ”ګوره، کوم آسونه چې د شمال طرف ته روان دى هغوئ زما غصه په شمال مُلک کښې سړه کړه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah6_verse_8.mp3', '', 1761754199, 1761754199);